def keep_customers(apps, schema_editor):
    """Every document keeps its customer.

    The customer a document was made for is in its frozen content (``customer_number``); that is the one, even if the
    project has been given to another customer since. A document whose content names none that exists still gets the
    customer its project has now.
    """
    from django.db.models.fields.json import KeyTextTransform

    Document = apps.get_model("documents", "Document")
    Customer = apps.get_model("customers", "Customer")
    Project = apps.get_model("projects", "Project")
    open_documents = Document.objects.filter(customer__isnull=True, project__isnull=False)
    by_number = dict(Customer.objects.values_list("number", "pk"))
    found: dict[int, list[int]] = {}
    # The number is read by the database (one value per document, not the whole content) and compared here.
    rows = (
        open_documents.annotate(frozen_number=KeyTextTransform("customer_number", "content"))
        .order_by()
        .values_list("pk", "frozen_number")
        .iterator(chunk_size=2000)
    )
    for pk, number in rows:
        customer_id = by_number.get(number) if isinstance(number, str) else None
        if customer_id is not None:
            found.setdefault(customer_id, []).append(pk)
    for customer_id, pks in found.items():
        for start in range(0, len(pks), 500):
            Document.objects.filter(pk__in=pks[start : start + 500]).update(customer_id=customer_id)
    Document.objects.filter(customer__isnull=True, project__isnull=False).update(
        customer_id=models.Subquery(Project.objects.filter(pk=models.OuterRef("project_id")).values("customer_id")[:1])
    )


def forget_customers(apps, schema_editor):
    """Reverse: the customer is that of the project again."""
    Document = apps.get_model("documents", "Document")
    Document.objects.update(customer=None)


def check_no_free_documents(apps, schema_editor):
    """Forward: nothing. Backward: stop while a document without a project exists.

    This is the last operation of the migration, so it is the first to be undone. Going back removes the customer
    and the draft tables and makes ``project`` required again; with a document that has no project that cannot
    work, and MariaDB would have undone part of the schema by then (it cannot roll back changes of the tables). The
    check comes before anything is changed.
    """
    Document = apps.get_model("documents", "Document")
    if Document.objects.filter(project__isnull=True).exists():
        raise IrreversibleError(
            "Documents without a project exist (offers, order confirmations or invoices made in Accounting). "
            "They cannot be kept when going back, because the earlier state has no such documents. Nothing was changed. "
            "Export or archive them, delete them in the database and try again."
        )


